<?php

$MOD = 998244353;

function mat_mult($a, $b) {
    $n = count($a);
    $c = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($k = 0; $k < $n; $k++) {
            if ($a[$i][$k] == 0) continue;
            for ($j = 0; $j < $n; $j++) {
                $c[$i][$j] = ($c[$i][$j] + $a[$i][$k] * $b[$k][$j]) % $MOD;
            }
        }
    }
    return $c;
}

function mat_pow($a, $p) {
    $n = count($a);
    $res = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) $res[$i][$i] = 1;
    while ($p > 0) {
        if ($p & 1) $res = mat_mult($res, $a);
        $a = mat_mult($a, $a);
        $p >>= 1;
    }
    return $res;
}

