<?php
const MOD = 998244353;

function main() {
    $line = trim(fgets(STDIN));
    list($n, $m) = array_map('intval', explode(' ', $line));
    $words = [];
    for ($i = 0; $i < $n; $i++) {
        $words[] = trim(fgets(STDIN));
    }

    // Build adjacency list: for each word, find all words that can follow it (overlap)
    $adj = [];
    foreach ($words as $w) {
        $adj[$w] = [];
    }
    foreach ($words as $a) {
        foreach ($words as $b) {
            $lenA = strlen($a);
            $lenB = strlen($b);
            $maxOverlap = min($lenA, $lenB);
            for ($k = $maxOverlap; $k >= 1; $k--) {
                if (substr($a, -$k) === substr($b, 0, $k)) {
                    $adj[$a][] = $b;
                    break;
                }
            }
        }
    }

    // Build transition matrix
    $size = count($words);
    $matrix = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        foreach ($adj[$words[$i]] as $next) {
            $j = array_search($next, $words);
            $matrix[$i][$j] = 1;
        }
    }

    // Matrix exponentiation
    function mat_mult($a, $b) {
        $n = count($a);
        $res = array_fill(0, $n, array_fill(0, $n, 0));
        for ($i = 0; $i < $n; $i++) {
            for ($k = 0; $k < $n; $k++) {
                if ($a[$i][$k] == 0) continue;
                for ($j = 0; $j < $n; $j++) {
                    $res[$i][$j] = ($res[$i][$j] + $a[$i][$k] * $b[$k][$j]) % MOD;
                }
            }
        }
        return $res;
    }

    function mat_pow($mat, $power) {
        $n = count($mat);
        $result = array_fill(0, $n, array_fill(0, $n, 0));
        for ($i = 0; $i < $n; $i++) {
            $result[$i][$i] = 1;
        }
        while ($power > 0) {
            if ($power % 2 == 1) {
                $result = mat_mult($result, $mat);
            }
            $mat = mat_mult($mat, $mat);
            $power = intdiv($power, 2);
        }
        return $result;
    }

    if ($m == 0) {
        echo 0;
        return;
    }

    $resultMat = mat_pow($matrix, $m - 1);

    // Sum all elements of the matrix
    $total = 0;
    for ($i = 0; $i < $size; $i++) {
        for ($j = 0; $j < $size; $j++) {
            $total = ($total + $resultMat[$i][$j]) % MOD;
        }
    }

    echo $total;
