<?php

const MOD = 998244353;

function main() {
    $input = file_get_contents("php://stdin");
    $lines = explode("\n", $input);
    $firstLine = explode(" ", trim($lines[0]));
    $n = (int)$firstLine[0];
    $m = (int)$firstLine[1];
    $words = [];
    for ($i = 0; $i < $n; $i++) {
        $words[] = trim($lines[$i + 1]);
    }

    // Build adjacency matrix
    $adj = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            if (canFollow($words[$i], $words[$j])) {
                $adj[$i][$j] = 1;
            }
        }
    }

    // Compute transition matrix T where T[i][j] = number of ways to transition from i to j
    $T = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            $T[$i][$j] = $adj[$i][$j];
        }
    }

    // Compute T^(m-1)
    $resultMatrix = matrixPower($T, $m - 1, $n);

    // Sum all elements of the resulting matrix
    $total = 0;
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            $total = ($total + $resultMatrix[$i][$j]) % MOD;
        }
    }

    echo $total . "\n";
}

function canFollow($prev, $next) {
    $prevLen = strlen($prev);
    $nextLen = strlen($next);
    if ($prevLen < $nextLen) {
        return substr($next, 0, $prevLen) === $prev;
    } else if ($prevLen > $nextLen) {
        return substr($prev, 0, $nextLen) === $next;
    } else {
        return $prev === $next;
    }
}

function matrixMultiply($A, $B, $size) {
    $result = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        for ($k = 0; $k < $size; $k++) {
            if ($A[$i][$k] == 0) continue;
            for ($j = 0; $j < $size; $j++) {
                $result[$i][$j] = ($result[$i][$j] + $A[$i][$k] * $B[$k][$j]) % MOD;
            }
        }
    }
    return $result;
}

function matrixPower($matrix, $power, $size) {
    // Initialize result as identity matrix
    $result = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        $result[$i][$i] = 1;
    }

    while ($power > 0) {
        if ($power % 2 == 1) {
            $result = matrixMultiply($result, $matrix, $size);
        }
        $matrix = matrixMultiply($matrix, $matrix, $size);
        $power = (int)($power / 2);
    }

    return $result;
}

main();
