        $words[] = trim($lines[$i + 1]);
    }

    $maxLen = 0;
    foreach ($words as $word) {
        $len = strlen($word);
        if ($len > $maxLen) {
            $maxLen = $len;
        }
    }

    $transitions = [];
    for ($i = 0; $i < $maxLen; $i++) {
        $transitions[$i] = [];
    }

    for ($i = 0; $i < $maxLen; $i++) {
        foreach ($words as $word) {
            $len = strlen($word);
            if ($len <= $i) continue;
            $transitions[$i][$len] = true;
        }
    }

    $matrixSize = $maxLen;
    $matrix = array_fill(0, $matrixSize, array_fill(0, $matrixSize, 0));
    for ($i = 0; $i < $matrixSize; $i++) {
        foreach ($transitions[$i] as $len => $val) {
            $next = $i + $len;
            if ($next <= $maxLen) {
                $matrix[$i][$next - 1]++;
            }
        }
    }

    $resultMatrix = matrixPower($matrix, $m, $MOD, $matrixSize);
    $result = 0;
    for ($i = 0; $i < $matrixSize; $i++) {
        $result = ($result + $resultMatrix[0][$i]) % $MOD;
    }
    echo $result . "\n";
}

function matrixMultiply($a, $b, $mod, $size) {
    $result = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        for ($k = 0; $k < $size; $k++) {
            if ($a[$i][$k] == 0) continue;
            for ($j = 0; $j < $size; $j++) {
                $result[$i][$j] = ($result[$i][$j] + $a[$i][$k] * $b[$k][$j]) % $mod;
            }
        }
    }
    return $result;
}

function matrixPower($matrix, $power, $mod, $size) {
    $result = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        $result[$i][$i] = 1;
    }
    $base = $matrix;
    while ($power > 0) {
        if ($power % 2 == 1) {
            $result = matrixMultiply($result, $base, $mod, $size);
        }
        $base = matrixMultiply($base, $base, $mod, $size);
        $power = (int)($power / 2);
    }
    return $result;
}

