                foreach ($col as $k => $val) {
                    if (!isset($result[$i][$k])) {
                        $result[$i][$k] = 0;
                    }
                    $result[$i][$k] = ($result[$i][$k] + $row[$j] * $val) % MOD;
                }
            }
        }
        return $result;
    }

