        $trans[$i] = [];
        for ($j = 0; $j <= $maxLen; $j++) {
            $trans[$i][$j] = 0;
        }
    }

    foreach ($words as $w) {
        $len = strlen($w);
        for ($i = 0; $i <= $maxLen - $len; $i++) {
            $trans[$i][$i + $len] = 1;
        }
    }

    $result = matMul(matPow($trans, $m), $trans);
    echo $result[0][0] % $MOD;
}

function matMul($a, $b) {
    global $MOD;
    $size = count($a);
    $result = [];
    for ($i = 0; $i < $size; $i++) {
        $result[$i] = [];
        for ($j = 0; $j < $size; $j++) {
            $sum = 0;
            for ($k = 0; $k < $size; $k++) {
                $sum = ($sum + $a[$i][$k] * $b[$k][$j]) % $MOD;
            }
            $result[$i][$j] = $sum;
        }
    }
    return $result;
}

function matPow($mat, $power) {
    global $MOD;
    $size = count($mat);
    $result = [];
    for ($i = 0; $i < $size; $i++) {
        $result[$i] = [];
        for ($j = 0; $j < $size; $j++) {
            $result[$i][$j] = ($i == $j) ? 1 : 0;
        }
    }

    while ($power > 0) {
        if ($power % 2 == 1) {
            $result = matMul($result, $mat);
        }
        $mat = matMul($mat, $mat);
        $power = intdiv($power, 2);
    }

    return $result;
}

