    $lenB = strlen($b);
    $totalLen = $lenA + $lenB;

    // Check all possible overlaps
    for ($overlap = 0; $overlap <= min($lenA, $lenB); $overlap++) {
        if ($overlap == 0) {
            // No overlap, just concatenate
            return true;
        }

        // Check if suffix of $a matches prefix of $b
        $suffixA = substr($a, -$overlap);
        $prefixB = substr($b, 0, $overlap);

        if ($suffixA === $prefixB) {
