            // The combined string is $a + $b with overlap
            $combined = $a . substr($b, $overlap);
            if (canSplitIntoWords($combined, $a, $b)) {
                return true;
            }
        }
    }

    return false;
}

function canSplitIntoWords($combined, $word1, $word2) {
    // Check if $combined can be split into $word1 followed by $word2
    // This is always true by construction, but let's verify
    $len1 = strlen($word1);
    $len2 = strlen($word2);
    $lenCombined = strlen($combined);

    if ($lenCombined != $len1 + $len2) {
        return false;
    }

    return substr($combined, 0, $len1) === $word1 && 
           substr($combined, $len1) === $word2;
}

function matrixMultiply($a, $b, $n) {
    $result = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            for ($k = 0; $k < $n; $k++) {
                $result[$i][$j] = ($result[$i][$j] + $a[$i][$k] * $b[$k][$j]) % MOD;
            }
        }
    }
    return $result;
}

function matrixPower($matrix, $power, $n) {
    // Initialize result as identity matrix
    $result = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
