function matrix_multiply($a, $b, $mod) {
    $n = count($a);
    $result = [];
    for ($i = 0; $i < $n; $i++) {
        $result[$i] = array_fill(0, $n, 0);
    }

    for ($i = 0; $i < $n; $i++) {
        for ($k = 0; $k < $n; $k++) {
            if ($a[$i][$k] == 0) continue;
            for ($j = 0; $j < $n; $j++) {
                $result[$i][$j] = ($result[$i][$j] + $a[$i][$k] * $b[$k][$j]) % $mod;
            }
        }
    }

    return $result;
}

