    }

    // Build adjacency matrix
    $adj = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            if (substr($words[$i], -1) === substr($words[$j], 0, 1)) {
                $adj[$i][$j] = 1;
            }
        }
    }

    // Matrix exponentiation
    $result = identity($n);
    $base = $adj;
    $power = $m - 1;
    while ($power > 0) {
        if ($power % 2 == 1) {
            $result = multiply($result, $base);
        }
        $base = multiply($base, $base);
        $power = intdiv($power, 2);
    }

    // Sum all elements in the result matrix
    $sum = 0;
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            $sum = ($sum + $result[$i][$j]) % MOD;
        }
    }
    echo $sum . "\n";
}

function identity($size) {
    $matrix = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        $matrix[$i][$i] = 1;
    }
    return $matrix;
}

function multiply($a, $b) {
    $size = count($a);
    $result = array_fill(0, $size, array_fill(0, $size, 0));
    for ($i = 0; $i < $size; $i++) {
        for ($j = 0; $j < $size; $j++) {
            if ($a[$i][$j] == 0) continue;
            for ($k = 0; $k < $size; $k++) {
                $result[$i][$k] = ($result[$i][$k] + $a[$i][$j] * $b[$j][$k]) % MOD;
            }
        }
    }
    return $result;
}

