<?php
$MOD = 998244353;

function main() {
    global $MOD;
    $n = 0;
    $m = 0;
    $words = [];
    $line = trim(fgets(STDIN));
    list($n, $m) = array_map('intval', explode(' ', $line));
    for ($i = 0; $i < $n; ++$i) {
        $words[] = trim(fgets(STDIN));
    }

    // Build adjacency matrix for transitions between words
    $adj = [];
    foreach ($words as $w1) {
        foreach ($words as $w2) {
            $adj[$w1][$w2] = 0;
        }
    }
    foreach ($words as $w1) {
        foreach ($words as $w2) {
            if (substr($w1, -1) === substr($w2, 0)) {
                $adj[$w1][$w2] = 1;
            }
        }
    }

    // Matrix multiplication
    function mat_mult($a, $b) {
        $n = count($a);
        $c = [];
        for ($i = 0; $i < $n; ++$i) {
            for ($j = 0; $j < $n; ++$j) {
                $c[$i][$j] = 0;
            }
        }
        for ($i = 0; $i < $n; ++$i) {
            for ($k = 0; $k < $n; ++$k) {
                if ($a[$i][$k] == 0) continue;
                for ($j = 0; $j < $n; ++$j) {
                    $c[$i][$j] = ($c[$i][$j] + $a[$i][$k] * $b[$k][$j]) % $GLOBALS['MOD'];
                }
            }
        }
        return $c;
    }

    // Matrix exponentiation
    function mat_pow($mat, $power) {
        $n = count($mat);
        $result = [];
        for ($i = 0; $i < $n; ++$i) {
            for ($j = 0; $j < $n; ++$j) {
                $result[$i][$j] = ($i == $j) ? 1 : 0;
            }
        }
        while ($power > 0) {
            if ($power % 2 == 1) {
                $result = mat_mult($result, $mat);
            }
            $mat = mat_mult($mat, $mat);
            $power = intdiv($power, 2);
        }
        return $result;
    }

    // Convert adjacency to numeric matrix
    $num_adj = [];
    foreach ($words as $w1) {
        $row = [];
        foreach ($words as $w2) {
            $row[] = $adj[$w1][$w2];
        }
        $num_adj[] = $row;
    }

    // Compute number of valid sequences of length m
    if ($m == 0) {
        echo 0;
        return;
    }
    $result_mat = mat_pow($num_adj, $m - 1);
    $total = 0;
    for ($i = 0; $i < count($words); ++$i) {
        for ($j = 0; $j < count($words); ++$j) {
            $total = ($total + $result_mat[$i][$j]) % $MOD;
        }
    }

    // Square the result for two independent hints
    $answer = ($total * $total) % $MOD;
    echo $answer;
}

main();
